from pathlib import Path
import json,csv
P=Path(__file__).resolve().parent;e=json.loads((P/'edits.json').read_text());n=json.loads((P/'notes.json').read_text());titles=json.loads((P/'titles.json').read_text())
def p(a,k,t):e[f'A{a:04d}-B{k:04d}']=t
p(572,2,'伊纳德，又称“低语之神”或“亡者之神”，据说是一位尚在孕育中的灵族神祇，由各方舟世界无限回路中亡者的灵魂滋养壮大。祂与血手凯恩的关系尚不清楚。按早期预言，只有最后一名艾达灵族死去，祂才会完全觉醒，将毁灭带给饥渴女士。伊纳德也是死神军的守护神，其追随者正努力促成祂的苏醒。')
p(572,4,'The rune of Ynnead 伊纳德的符文')
p(572,7,'伊纳德寄托着衰亡灵族最后的希望。他们相信，当无限回路收容了全族灵魂，各方舟的回路便会合为一体。亡者共同凝聚出新的亚空间力量，与色孽交战并将其制服，让灵族灵魂再次融为平衡统一的存在。他们希望，若这一切能够实现，整个种族便可化为更好的形态重生。在此之前，方舟世界与魂石必须得到保护，继续存在；生者也必须理解、铭记灵族的美德，使这些理念随灵魂一同进入无限回路。')
p(572,9,'灵族不断死去，灵魂汇入无限回路，伊纳德的力量也随之增长。少数先知相信，待全族最后一个个体死亡，祂便会觉醒，获得彻底击败色孽的力量。991.M41，灵族秘术师凯萨杜拉斯宣称，在终焉之刻，灵族唯一的生存希望便是伊纳德。')
p(572,11,'The birth of Ynnead 伊纳德的诞生')
p(572,14,'艾尔德拉德·乌瑟兰曾试图举行盛大仪式，借各无限回路汇聚大先知遗存的力量，提前唤醒伊纳德。仪式将使全部方舟世界陷于瘫痪，严重干扰星炬，却也可能最终终结色孽。然而，在德梅斯努斯港之战中，死亡守望挫败了这一计划。')
p(572,16,'后来，死神军成立，再度寻求唤醒伊纳德。伊芙蕾妮率领他们寻找老妪之剑，希望借“第七道途”仪式，让亡者之神苏醒，而无须牺牲整个灵族。伊纳德已开始觉醒，其化身因卡恩也随之显现。')
titles['572']='伊纳德 Ynnead'
n.update({'A0572-B0002':'Ynnead沿官方完整名称“伊纳德信徒”采用词根伊纳德，原因尼德保留原篇名和原译；prohesised疑为prophesied，指预言，不是有人怀疑。Aeldari为整个种族，非只指方舟灵族。开头未显现与末尾已开始觉醒属于资料时期差异，以早期预言衔接。','A0572-B0007':'原英文 merge with it 代词所指含混，按后续single balanced entity表述为灵魂形成统一存在，不擅自断言与色孽融合。','A0572-B0014':'remains与channeling关系在英文中较简略，译遗存的力量而非把遗体实体运过每条回路；仪式结果保持would/may的未实现语气。'})
p(573,2,'黑暗灵族（Drukhari，旧称 Dark Eldar）与阿苏焉尼及其他艾达灵族同出一族，属于古老而先进、外貌近似精灵的类人种族。他们的军队通常以速度与技术见长，却相对缺乏人数和承受打击的能力。黑暗灵族沉迷劫掠、奴役与酷刑，残忍至极。他们乘先进的反重力悬浮艇，运送大批战士发起高速袭击；又借横跨银河、连通异维度的网道迷宫来去自如，常毫无预警地突然出现，在敌人组织有效反击之前，便带着俘虏消失。')
p(573,6,'黑暗灵族并不依靠占据大量行星维生，而主要聚居于暗城科摩罗。他们大多从事劫掠，有时也受雇为佣兵。')
p(573,10,'阿斯鲁拜尔·维克特是科摩罗及整个黑暗灵族的至高霸主。“黑暗灵族”一名也源于他：M32，他首次公开以“Eladrith Ynneas”自称，意即黑暗灵族。')
p(573,14,'黑暗灵族的起源，要追溯到几乎毁灭整个种族的“灵族陨落”。这场灾难夺走数万亿灵族的生命，撕裂现实与亚空间之间的屏障，并使混沌之神色孽诞生。')
p(573,18,'灵族的心智极其复杂，感官敏锐得足以分辨人类难以察觉的细节，情感更强烈得让人类的体验相形见绌。他们聪慧异常，思考也远快于人类，因此对宇宙与一切感受的体验，都远为深刻。在亚空间中，灵族的灵魂也比所谓“低等”智慧生物明亮得多，更能影响这个非物质领域。所有灵族都有潜在的灵能天赋，经训练后可变得极其强大；而灵魂过于强盛，恰是其衰亡的原因之一。陨落前，灵族拥有横跨银河、包含数百万世界的帝国，规模与力量甚至超过鼎盛的人类帝国。他们生活相对安宁：欧克等野蛮种族的数量受控，无力威胁其霸权；人类尚未变得极度仇视异形，也没有广阔疆域；泰伦虫巢舰队尚未出现于其认知之中。古老宿敌星神与太空死灵，则已战败、沉眠。')
p(573,20,'灵族世界宛如乐园。精密无比的机器承担劳动与生产，让居民自由追求艺术与审美。琐务尽被代劳，灵族渐趋懒散、腐化，在数千年间越来越沉溺享乐。传统与秩序妨碍欲望，便被逐步抛弃；“欢愉教派”应运而生，追逐极致感官刺激，仪式日渐狂野，最终沦为对同胞施暴、活祭。一些灵族厌恶这种堕落，离开母星，迁往未受开发的少女世界，或乘新建方舟远去，留下欢愉教派继续疯狂。按本节记述，灵族在这一时期发现、掌握网道，并于其中建立领地与前哨，作为跨越群星的港口，科摩罗由此兴起。与外界隔绝的暗城，很快成为欢愉教派与愈发堕落行径的温床。')
p(573,22,'与此同时，可怕的存在正在亚空间中孕育。数千年的放纵对灵能领域产生深远影响，使一种混沌力量逐渐成形。它不断壮大，轮廓日益清晰，最终迸发出意识——庞大、邪恶，对灵族灵魂有着无底的饥渴。这便是色孽。孕育过程历时数千年，与人类纷争时代大致相重合；真正诞生时，灾变却来得突如其来、毁天灭地。灵能冲击波横扫银河，几乎所有灵族的灵魂都在瞬间被剥离，由新生的混沌神吞噬。幸存者寥寥，且多数陷入疯狂，心智一半困于现实，一半陷于亚空间的混乱。巨大裂口吞没了灵族帝国，形成恐惧之眼。')
p(573,24,'科摩罗居民却藏在网道深处，避过色孽诞生时的吞噬。网道虽大面积损毁，他们仍活了下来，而且不同于方舟同胞，丝毫不愿悔改。不久，他们发现色孽仍在缓缓蚕食自身灵魂，也找到抵抗之法：吸收他人灵魂的痛苦与折磨，可以使自己重获活力、逃过死亡。只要能持续“进食”，网道居民的身体便可摆脱岁月侵蚀。他们遂开始劫掠现实宇宙，搜捕奴隶与俘虏。除维生需要外，色孽对灵魂的侵蚀也让许多人逐渐嗜好他人的苦难。黑暗灵族由此形成：一群虐杀成性的劫掠者，以受害者的痛苦维系自身灵魂。在这座恐怖之城中，残酷的阿斯鲁拜尔·维克特崛起，清洗对手，成为数千年来无人能挑战的霸主。')
p(573,29,'自科摩罗建立以来，黑暗灵族历史通常分为四个主要时期：黑暗起源时代、痛苦时代、丰饶时代，以及活体缪斯时代。')
p(573,31,'大裂隙形成后——黑暗灵族称其为“达瑟迪安”——科摩罗经历连番动荡。大规模析离使恶魔蜂拥而入，最著名的冲突是凯恩之门之战。局势虽渐趋稳定，死神军兴起等变化又带来新的纷争，最终引发黑暗灵族内战。维克特重生为活体黑暗缪斯，试图肃清死神军在暗城日益扩大的影响。尽管遭遇这些挫折，黑暗灵族的劫掠规模仍空前高涨，丝毫没有停止靠折磨他人维生的迹象。')
p(573,34,'黑暗灵族与其他同族一样，身材高挑、动作轻盈，耳朵尖细，目光锐利。不过，世代厮杀与暗城生活，使他们形成一些显著差异：缺乏阳光的科摩罗，让皮肤苍白得近乎透明；历经数千年的战斗性状选育，普通黑暗灵族战士的力量与反应，甚至超过方舟同胞。埃沃勒斯大屠杀的影像，须放慢到四分之一速度，才能看清阴谋团战士屠杀帝国平民的动作。关于他们闪避激光射击、将破片手榴弹踢回敌阵的故事屡见不鲜；角斗场中的一名巫灵，便足以胜过十名人类战士。他们的感官也更敏锐，即使在漆黑中，仍能清楚看见敌人。')
p(573,38,'然而，黑暗灵族灵能者几乎闻所未闻。一部分原因在于，他们注重肉体能力，天生的灵能逐渐萎缩；更重要的是，数千年的选择性繁衍，以及维克特对灵能者的处决，压制了这一天赋，以免有人无意间为恶魔打开入口。施展灵能还会引来色孽注意，因此成为科摩罗少数明确禁止的行为之一，外来者也不例外。灵能痕迹微弱，使黑暗灵族常能避开大先知的预见，成为少数可悄然接近方舟世界的势力。不过，生活在科摩罗之外、例如加入海盗的黑暗灵族，若得到其他同族指点，仍可能慢慢恢复较弱的灵能。')
p(573,41,'黑暗灵族与多数同族一样，掌握反重力、暗光武器、纳米技术及灵能造物等先进手段。但这些装备由制造工艺生产，而非以灵能催生。黑暗灵族虽使用灵能装置，却不亲自施展灵能，因为引导亚空间能量，会招来饥渴女士的注视，祸及整个种族。因此，方舟同胞习以为常的灵能技艺，在科摩罗的暗塔中属于少数禁忌之一。')
p(573,44,'岁月越久，黑暗灵族越受“饥渴”折磨，吞饮其他生灵灵魂的欲望愈发强烈，几乎压倒一切。据推测，大敌色孽在他们活着时，就不断抽取灵魂精髓。黑暗灵族通过饮魂抵御这种侵蚀：也许是暂时满足色孽，也许是用他人灵魂补足自身损失。若真正死去，他们的整个灵魂仍会被祂吞没。黑暗灵族寿命漫长，却并非绝对不死；饮魂能够恢复活力、逆转衰老，只要补给不断，便可避免因老死而落入色孽之手。受害者通常来自劫掠所获的俘虏。不过，他们并不把折磨视作无奈的生存手段，而是乐在其中。')
p(573,48,'科摩罗居民残酷、自私，几无怜悯可言。暴力内斗司空见惯，只有维克特的铁腕，压住了全面失序。在这样的社会中求生，必须冷酷自立，奉行弱肉强食。任何同情都不只令人鄙夷，更会成为敌人可乘之机，反伤自身。即便血亲之间，也难言情谊：背叛、暗算、夺权随处可见，统治者甚至鼓励这种风气，尤其是维克特，以此使潜在反对者永远分裂。')
n.update({'A0573-B0018':'lesser 为轻蔑意义的低等，不是体型较小；早期人类疆域、星神和死灵战败叙述按原文时期与版本保留。','A0573-B0020':'left on newly-constructed Craftworlds 指乘方舟离去，原译离开方舟方向错误。此段网道发现时间与571、563古圣传授的叙述不一致，保留出处差异。','A0573-B0029':'Age of Plenty丰饶时代；Living Muse按活体缪斯理解，不将Muse当个人名。','A0573-B0031':'Dysjunction与571统一析离，而非笼统连接异常；Ynnari统一死神军。','A0573-B0034':'bred for combat 为长期选育，不只是训练；pict-captures为影像记录，不是需放慢的静态图片。','A0573-B0038':'even by outsiders补出禁令也适用于外来者；Farseer大先知与普通先知分开。'})
for fn,obj in [('edits.json',e),('notes.json',n),('titles.json',titles)]:(P/fn).write_text(json.dumps(obj,ensure_ascii=False,indent=2))
